[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>CreativeHub — Online Classes for Creatives</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        :root {
            --black: #000000;
            --green: #55DA9B;
            --purple: #5620C1;
            --white: #FFFFFF;
            --off-white: #F8F7F4;
            --charcoal: #1A1A2E;
            --coral: #FF6B4A;
            --gray-100: #F3F4F6;
            --gray-200: #E5E7EB;
            --gray-300: #D1D5DB;
            --gray-400: #9CA3AF;
            --gray-500: #6B7280;
            --gray-600: #4B5563;
            --gray-700: #374151;
            --gray-800: #1F2937;
            --radius-sm: 8px;
            --radius-md: 12px;
            --radius-lg: 16px;
            --radius-xl: 24px;
            --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
            --shadow-md: 0 4px 6px rgba(0,0,0,0.07);
            --shadow-lg: 0 10px 25px rgba(0,0,0,0.1);
            --shadow-xl: 0 20px 40px rgba(0,0,0,0.15);
        }

        body {
            font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
            background: var(--white);
            color: var(--gray-800);
            line-height: 1.6;
            -webkit-font-smoothing: antialiased;
        }

        .container {
            max-width: 1280px;
            margin: 0 auto;
            padding: 0 24px;
        }

        /* Navigation */
        .nav {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 100;
            background: rgba(255,255,255,0.95);
            backdrop-filter: blur(10px);
            border-bottom: 1px solid var(--gray-200);
        }

        .nav-inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 72px;
        }

        .logo {
            font-size: 24px;
            font-weight: 800;
            color: var(--black);
            text-decoration: none;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .logo-icon {
            width: 36px;
            height: 36px;
            background: linear-gradient(135deg, var(--green), var(--purple));
            border-radius: var(--radius-sm);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .logo-icon svg {
            width: 20px;
            height: 20px;
            fill: white;
        }

        .nav-links {
            display: flex;
            align-items: center;
            gap: 32px;
        }

        .nav-link {
            font-size: 15px;
            font-weight: 500;
            color: var(--gray-600);
            text-decoration: none;
            transition: color 0.2s;
        }

        .nav-link:hover {
            color: var(--black);
        }

        .nav-actions {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            font-family: inherit;
            font-size: 15px;
            font-weight: 600;
            padding: 12px 24px;
            border-radius: var(--radius-md);
            border: none;
            cursor: pointer;
            transition: all 0.2s;
            text-decoration: none;
        }

        .btn-primary {
            background: var(--coral);
            color: white;
        }

        .btn-primary:hover {
            background: #E85A3A;
            transform: translateY(-1px);
            box-shadow: var(--shadow-lg);
        }

        .btn-secondary {
            background: var(--black);
            color: white;
        }

        .btn-secondary:hover {
            background: var(--gray-800);
            transform: translateY(-1px);
        }

        .btn-ghost {
            background: transparent;
            color: var(--gray-600);
        }

        .btn-ghost:hover {
            background: var(--gray-100);
            color: var(--black);
        }

        .btn-lg {
            padding: 16px 32px;
            font-size: 16px;
        }

        .btn-sm {
            padding: 8px 16px;
            font-size: 14px;
        }

        /* Hero */
        .hero {
            background: var(--charcoal);
            padding: 140px 0 80px;
            position: relative;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: -50%;
            right: -20%;
            width: 800px;
            height: 800px;
            background: radial-gradient(circle, rgba(86,32,193,0.3) 0%, transparent 70%);
            pointer-events: none;
        }

        .hero::after {
            content: '';
            position: absolute;
            bottom: -30%;
            left: -10%;
            width: 600px;
            height: 600px;
            background: radial-gradient(circle, rgba(85,218,155,0.2) 0%, transparent 70%);
            pointer-events: none;
        }

        .hero-content {
            position: relative;
            z-index: 1;
            text-align: center;
            max-width: 900px;
            margin: 0 auto;
        }

        .hero h1 {
            font-size: clamp(40px, 6vw, 64px);
            font-weight: 800;
            color: var(--white);
            line-height: 1.1;
            margin-bottom: 20px;
            letter-spacing: -0.02em;
        }

        .hero-subtitle {
            font-size: 20px;
            color: var(--gray-400);
            margin-bottom: 40px;
        }

        .hero-ctas {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 16px;
            margin-bottom: 48px;
            flex-wrap: wrap;
        }

        .btn-google {
            background: var(--white);
            color: var(--gray-800);
            box-shadow: var(--shadow-md);
        }

        .btn-google:hover {
            background: var(--gray-100);
            transform: translateY(-2px);
            box-shadow: var(--shadow-xl);
        }

        .btn-google svg {
            width: 20px;
            height: 20px;
        }

        .hero-legal {
            font-size: 12px;
            color: var(--gray-500);
            max-width: 480px;
            margin: 0 auto;
            line-height: 1.5;
        }

        /* Category Pills */
        .category-pills {
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
            justify-content: center;
            margin-top: 48px;
        }

        .category-pill {
            padding: 10px 20px;
            background: rgba(255,255,255,0.1);
            border: 1px solid rgba(255,255,255,0.15);
            border-radius: 100px;
            color: var(--gray-300);
            font-size: 14px;
            font-weight: 500;
            text-decoration: none;
            transition: all 0.2s;
            white-space: nowrap;
        }

        .category-pill:hover {
            background: rgba(255,255,255,0.2);
            color: var(--white);
            border-color: rgba(255,255,255,0.3);
        }

        /* Features */
        .features {
            padding: 100px 0;
            background: var(--off-white);
        }

        .section-header {
            text-align: center;
            margin-bottom: 60px;
        }

        .section-title {
            font-size: clamp(32px, 4vw, 44px);
            font-weight: 800;
            color: var(--black);
            margin-bottom: 16px;
            letter-spacing: -0.02em;
        }

        .section-subtitle {
            font-size: 18px;
            color: var(--gray-500);
            max-width: 600px;
            margin: 0 auto;
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
        }

        .feature-card {
            background: var(--white);
            padding: 32px;
            border-radius: var(--radius-xl);
            box-shadow: var(--shadow-sm);
            transition: all 0.3s;
        }

        .feature-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-lg);
        }

        .feature-icon {
            width: 56px;
            height: 56px;
            background: linear-gradient(135deg, var(--green), #3DB97A);
            border-radius: var(--radius-md);
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
        }

        .feature-icon svg {
            width: 28px;
            height: 28px;
            fill: white;
        }

        .feature-card h3 {
            font-size: 20px;
            font-weight: 700;
            color: var(--black);
            margin-bottom: 8px;
        }

        .feature-card p {
            font-size: 15px;
            color: var(--gray-500);
            line-height: 1.6;
        }

        /* Stats */
        .stats {
            background: linear-gradient(135deg, var(--purple) 0%, #7B3FD9 100%);
            padding: 80px 0;
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 48px;
            text-align: center;
        }

        .stat-item {
            color: var(--white);
        }

        .stat-value {
            font-size: clamp(48px, 6vw, 72px);
            font-weight: 800;
            line-height: 1;
            margin-bottom: 8px;
        }

        .stat-label {
            font-size: 16px;
            opacity: 0.85;
            font-weight: 500;
        }

        /* Courses */
        .courses {
            padding: 100px 0;
        }

        .course-tabs {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
            justify-content: center;
            margin-bottom: 48px;
        }

        .course-tab {
            padding: 12px 24px;
            background: var(--gray-100);
            border: none;
            border-radius: 100px;
            font-family: inherit;
            font-size: 14px;
            font-weight: 600;
            color: var(--gray-600);
            cursor: pointer;
            transition: all 0.2s;
        }

        .course-tab:hover {
            background: var(--gray-200);
            color: var(--gray-800);
        }

        .course-tab.active {
            background: var(--black);
            color: var(--white);
        }

        .courses-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 24px;
        }

        .course-card {
            background: var(--white);
            border-radius: var(--radius-lg);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
            transition: all 0.3s;
            border: 1px solid var(--gray-200);
        }

        .course-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-lg);
            border-color: transparent;
        }

        .course-thumb {
            width: 100%;
            aspect-ratio: 16/10;
            background: linear-gradient(135deg, var(--gray-200), var(--gray-300));
            position: relative;
            overflow: hidden;
        }

        .course-thumb-inner {
            position: absolute;
            inset: 0;
            background: linear-gradient(135deg, var(--purple) 0%, var(--green) 100%);
            opacity: 0.9;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .course-thumb-inner svg {
            width: 48px;
            height: 48px;
            fill: white;
            opacity: 0.5;
        }

        .course-info {
            padding: 20px;
        }

        .course-title {
            font-size: 16px;
            font-weight: 700;
            color: var(--black);
            margin-bottom: 8px;
            line-height: 1.4;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        .course-instructor {
            font-size: 14px;
            color: var(--gray-500);
            margin-bottom: 12px;
        }

        .course-meta {
            display: flex;
            align-items: center;
            gap: 16px;
            font-size: 13px;
            color: var(--gray-400);
        }

        .course-meta span {
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .course-meta svg {
            width: 14px;
            height: 14px;
            fill: currentColor;
        }

        /* Creative Feed */
        .creative-feed {
            padding: 100px 0;
            background: var(--off-white);
        }

        .feed-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
            gap: 24px;
        }

        .feed-card {
            background: var(--white);
            padding: 40px;
            border-radius: var(--radius-xl);
            box-shadow: var(--shadow-sm);
            transition: all 0.3s;
        }

        .feed-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-lg);
        }

        .feed-icon {
            width: 64px;
            height: 64px;
            background: linear-gradient(135deg, var(--coral), #FF8F70);
            border-radius: var(--radius-md);
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 24px;
        }

        .feed-icon.green {
            background: linear-gradient(135deg, var(--green), #3DB97A);
        }

        .feed-icon.purple {
            background: linear-gradient(135deg, var(--purple), #7B3FD9);
        }

        .feed-icon svg {
            width: 32px;
            height: 32px;
            fill: white;
        }

        .feed-card h3 {
            font-size: 22px;
            font-weight: 700;
            color: var(--black);
            margin-bottom: 12px;
        }

        .feed-card p {
            font-size: 15px;
            color: var(--gray-500);
            line-height: 1.6;
        }

        /* Teachers */
        .teachers {
            padding: 100px 0;
            overflow: hidden;
        }

        .teachers-carousel-wrapper {
            position: relative;
            margin: 0 -24px;
            padding: 0 24px;
        }

        .teachers-carousel {
            display: flex;
            gap: 24px;
            overflow-x: auto;
            scroll-behavior: smooth;
            scrollbar-width: none;
            -ms-overflow-style: none;
            padding: 20px 0;
        }

        .teachers-carousel::-webkit-scrollbar {
            display: none;
        }

        .teacher-card {
            flex: 0 0 240px;
            background: var(--white);
            border-radius: var(--radius-xl);
            padding: 32px 24px;
            text-align: center;
            box-shadow: var(--shadow-sm);
            border: 1px solid var(--gray-200);
            transition: all 0.3s;
        }

        .teacher-card:hover {
            transform: translateY(-4px);
            box-shadow: var(--shadow-lg);
            border-color: transparent;
        }

        .teacher-avatar {
            width: 100px;
            height: 100px;
            border-radius: 50%;
            margin: 0 auto 20px;
            background: linear-gradient(135deg, var(--purple), var(--green));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 36px;
            font-weight: 700;
            color: white;
        }

        .teacher-name {
            font-size: 18px;
            font-weight: 700;
            color: var(--black);
            margin-bottom: 4px;
        }

        .teacher-specialty {
            font-size: 14px;
            color: var(--gray-500);
        }

        .carousel-nav {
            display: flex;
            justify-content: center;
            gap: 12px;
            margin-top: 32px;
        }

        .carousel-btn {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            border: 2px solid var(--gray-200);
            background: var(--white);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s;
        }

        .carousel-btn:hover {
            border-color: var(--black);
            background: var(--black);
        }

        .carousel-btn:hover svg {
            fill: white;
        }

        .carousel-btn svg {
            width: 20px;
            height: 20px;
            fill: var(--gray-600);
            transition: fill 0.2s;
        }

        /* Testimonials */
        .testimonials {
            padding: 100px 0;
            background: var(--charcoal);
        }

        .testimonials .section-title {
            color: var(--white);
        }

        .testimonials-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
        }

        .testimonial-card {
            background: rgba(255,255,255,0.05);
            border: 1px solid rgba(255,255,255,0.1);
            border-radius: var(--radius-xl);
            padding: 32px;
            transition: all 0.3s;
        }

        .testimonial-card:hover {
            background: rgba(255,255,255,0.08);
            border-color: rgba(255,255,255,0.2);
        }

        .testimonial-quote {
            font-size: 16px;
            color: var(--gray-300);
            line-height: 1.7;
            margin-bottom: 24px;
            font-style: italic;
        }

        .testimonial-author {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .testimonial-avatar {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--green), var(--purple));
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            color: white;
            font-size: 18px;
        }

        .testimonial-name {
            font-size: 15px;
            font-weight: 600;
            color: var(--white);
        }

        .testimonial-role {
            font-size: 13px;
            color: var(--gray-400);
        }

        /* Teams */
        .teams {
            padding: 100px 0;
            background: linear-gradient(135deg, var(--green) 0%, #3DB97A 100%);
        }

        .teams-content {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 60px;
            flex-wrap: wrap;
        }

        .teams-text {
            flex: 1;
            min-width: 300px;
        }

        .teams .section-title {
            color: var(--white);
            text-align: left;
        }

        .teams-body {
            font-size: 18px;
            color: rgba(255,255,255,0.9);
            line-height: 1.7;
            margin-top: 16px;
            max-width: 560px;
        }

        .teams-cta {
            flex: 0 0 auto;
        }

        .btn-white {
            background: var(--white);
            color: var(--black);
        }

        .btn-white:hover {
            background: var(--gray-100);
            transform: translateY(-2px);
            box-shadow: var(--shadow-xl);
        }

        /* FAQ */
        .faq {
            padding: 100px 0;
        }

        .faq-list {
            max-width: 800px;
            margin: 0 auto;
        }

        .faq-item {
            border-bottom: 1px solid var(--gray-200);
        }

        .faq-question {
            width: 100%;
            padding: 24px 0;
            background: none;
            border: none;
            display: flex;
            align-items: center;
            justify-content: space-between;
            cursor: pointer;
            font-family: inherit;
            text-align: left;
        }

        .faq-question span {
            font-size: 18px;
            font-weight: 600;
            color: var(--black);
        }

        .faq-icon {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: var(--gray-100);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.3s;
            flex-shrink: 0;
        }

        .faq-icon svg {
            width: 16px;
            height: 16px;
            fill: var(--gray-600);
            transition: transform 0.3s;
        }

        .faq-item.active .faq-icon {
            background: var(--black);
        }

        .faq-item.active .faq-icon svg {
            fill: white;
            transform: rotate(45deg);
        }

        .faq-answer {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out;
        }

        .faq-answer-inner {
            padding: 0 0 24px;
            font-size: 16px;
            color: var(--gray-600);
            line-height: 1.7;
        }

        .faq-item.active .faq-answer {
            max-height: 300px;
        }

        /* Footer */
        .footer {
            background: var(--black);
            padding: 80px 0 40px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
            gap: 48px;
            margin-bottom: 60px;
        }

        .footer-col h4 {
            font-size: 14px;
            font-weight: 700;
            color: var(--white);
            margin-bottom: 20px;
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }

        .footer-col ul {
            list-style: none;
        }

        .footer-col li {
            margin-bottom: 12px;
        }

        .footer-col a {
            font-size: 14px;
            color: var(--gray-400);
            text-decoration: none;
            transition: color 0.2s;
        }

        .footer-col a:hover {
            color: var(--white);
        }

        .footer-bottom {
            padding-top: 40px;
            border-top: 1px solid var(--gray-700);
            display: flex;
            align-items: center;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 16px;
        }

        .footer-legal {
            font-size: 13px;
            color: var(--gray-500);
            max-width: 600px;
        }

        .footer-links {
            display: flex;
            gap: 24px;
        }

        .footer-links a {
            font-size: 13px;
            color: var(--gray-400);
            text-decoration: none;
        }

        .footer-links a:hover {
            color: var(--white);
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .stats-grid {
                grid-template-columns: repeat(2, 1fr);
                gap: 40px;
            }
        }

        @media (max-width: 768px) {
            .nav-links {
                display: none;
            }

            .hero {
                padding: 120px 0 60px;
            }

            .hero h1 {
                font-size: 36px;
            }

            .hero-ctas {
                flex-direction: column;
                align-items: stretch;
            }

            .hero-ctas .btn {
                width: 100%;
            }

            .stats-grid {
                grid-template-columns: repeat(2, 1fr);
                gap: 32px;
            }

            .stat-value {
                font-size: 40px;
            }

            .courses-grid {
                grid-template-columns: 1fr;
            }

            .teacher-card {
                flex: 0 0 200px;
            }

            .teams-content {
                flex-direction: column;
                text-align: center;
            }

            .teams .section-title {
                text-align: center;
            }

            .teams-body {
                max-width: none;
            }

            .footer-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .footer-bottom {
                flex-direction: column;
                text-align: center;
            }
        }

        @media (max-width: 480px) {
            .container {
                padding: 0 16px;
            }

